/**
 * Repoints every issue carrying `sourceLabelId` onto `targetLabelId`, then
 * removes the source label. Runs inside one transaction so a crash midway
 * never leaves issues relabelled without the source being retired (or vice
 * versa).
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<{ issuesRelabelled: number }> {
  const db = getDb();

  return db.transaction((tx) => {
    const sourceRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
